mapper.insert:
insert into ygb_worker_feedback (
    user_id, person_id, person_name, mobile, title, content, contact_mobile, status, create_by, create_time, del_flag
) values (
    #{userId}, #{personId}, #{personName}, #{mobile}, #{title}, #{content}, #{contactMobile}, #{status},
    #{createBy}, sysdate(), '0'
)

insert into ygb_worker_setting (
    user_id, person_id, notify_enabled, push_client_id, notification_permission, push_platform, create_by, create_time, del_flag
) values (
    #{userId}, #{personId}, #{notifyEnabled}, #{pushClientId}, #{notificationPermission}, #{pushPlatform},
    #{createBy}, sysdate(), '0'
)

insert into ygb_worker_point_ledger (
    user_id, person_id, person_name, change_type, title, summary, score_delta, balance_after, create_by, create_time, del_flag
) values (
    #{userId}, #{personId}, #{personName}, #{changeType}, #{title}, #{summary}, #{scoreDelta}, #{balanceAfter}, #{createBy}, sysdate(), '0'
)

mapper.select:
select upload_id, user_id, person_id, person_name, category_code, category_name, file_url, file_name, original_filename, file_size, content_type, source_module, create_by, create_time, update_by, update_time, remark, del_flag from ygb_worker_upload_record where del_flag = '0' and user_id = #{userId}
and category_code = #{categoryCode}
order by upload_id desc
